1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// statusInStation 表示包裹当前在某站点（已收件或已完成交接）。
15	const statusInStation = "在站"
16	
17	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
18	type Event struct {
19		Op      string    `json:"op"`                // 收件 | 交接
20		Station string    `json:"station"`           // 与该操作有关的站点
21		Time    time.Time `json:"time"`              // 发生时间
22		Request string    `json:"request,omitempty"` // 交接请求号（收件记录为空）
23	}
24	
25	// Parcel 是一件包裹的台账信息。
26	type Parcel struct {
27		ID         string    `json:"id"`
28		Station    string    `json:"station"`    // 当前归属站点
29		Status     string    `json:"status"`     // 当前状态
30		Registered time.Time `json:"registered"` // 收件时间
31		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
32	}
33	
34	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
35	type HandoffResult struct {
36		Request string    `json:"request"`
37		From    string    `json:"from"`
38		To      string    `json:"to"`
39		Parcels []string  `json:"parcels"` // 按首次提交时给出的顺序保存
40		Time    time.Time `json:"time"`
41	}
42	
43	// ledgerFile 是本地数据文件的磁盘结构。
44	type ledgerFile struct {
45		Version  int                       `json:"version"`
46		Parcels  map[string]*Parcel        `json:"parcels"`
47		Handoffs map[string]*HandoffResult `json:"handoffs"`
48	}
49	
50	// Store 是一个数据文件对应的包裹站点交接台账。
51	type Store struct {
52		path string
53		data ledgerFile
54	}
55	
56	var (
57		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
58		ErrCorrupt = errors.New("数据文件已损坏")
59		// ErrNotFound 表示包裹编号在台账中不存在。
60		ErrNotFound = errors.New("包裹不存在")
61	)
62	
63	// Open 打开（或在文件不存在时建立）一个本地台账。
64	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
65	func Open(path string) (*Store, error) {
66		s := &Store{path: path}
67		raw, err := os.ReadFile(path)
68		if err != nil {
69			if os.IsNotExist(err) {
70				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{}}
71				return s, nil
72			}
73			return nil, fmt.Errorf("读取数据文件失败: %w", err)
74		}
75		if len(bytes.TrimSpace(raw)) == 0 {
76			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
77		}
78		if err := json.Unmarshal(raw, &s.data); err != nil {
79			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
80		}
81		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
82			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
83		}
84		if err := s.data.validate(); err != nil {
85			return nil, err
86		}
87		return s, nil
88	}
89	
90	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
91	func (l *ledgerFile) validate() error {
92		for id, p := range l.Parcels {
93			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
94				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
95			}
96		}
97		for req, h := range l.Handoffs {
98			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
99				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
100			}
101			for _, id := range h.Parcels {
102				if _, ok := l.Parcels[id]; !ok {
103					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
104				}
105			}
106		}
107		return nil
108	}
109	
110	// Register 执行单件收件登记并将结果整体落盘。
111	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
112		if _, ok := s.data.Parcels[id]; ok {
113			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
114		}
115		p := &Parcel{
116			ID:         id,
117			Station:    station,
118			Status:     statusInStation,
119			Registered: now,
120			Trail: []Event{{
121				Op:      "收件",
122				Station: station,
123				Time:    now,
124			}},
125		}
126		s.data.Parcels[id] = p
127		if err := s.save(); err != nil {
128			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
129			return nil, err
130		}
131		return p, nil
132	}
133	
134	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
135	func (s *Store) Query(id string) (*Parcel, error) {
136		p, ok := s.data.Parcels[id]
137		if !ok {
138			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
139		}
140		return p, nil
141	}
142	
143	// Handoff 提交一次多件包裹的站点交接。
144	//
145	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
146	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
147	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
148	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
149	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
150		if saved, ok := s.data.Handoffs[request]; ok {
151			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
152				return saved, true, nil
153			}
154			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
155		}
156	
157		// 首次提交：先做全部校验，任何一件不满足都整体失败。
158		for _, id := range parcels {
159			p, ok := s.data.Parcels[id]
160			if !ok {
161				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
162			}
163			if p.Station != from {
164				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
165			}
166		}
167	
168		res := &HandoffResult{
169			Request: request,
170			From:    from,
171			To:      to,
172			Parcels: append([]string(nil), parcels...),
173			Time:    now,
174		}
175		s.data.Handoffs[request] = res
176	
177		// 记录旧值，落盘失败时整体回滚。
178		prev := make(map[string]struct {
179			station string
180			trail   []Event
181		}, len(parcels))
182		for _, id := range parcels {
183			p := s.data.Parcels[id]
184			prev[id] = struct {
185				station string
186				trail   []Event
187			}{p.Station, append([]Event(nil), p.Trail...)}
188			p.Station = to
189			p.Status = statusInStation
190			p.Trail = append(p.Trail, Event{
191				Op:      "交接",
192				Station: to,
193				Request: request,
194				Time:    now,
195			})
196		}
197	
198		if err := s.save(); err != nil {
199			delete(s.data.Handoffs, request)
200			for id, old := range prev {
201				p := s.data.Parcels[id]
202				p.Station = old.station
203				p.Trail = old.trail
204			}
205			return nil, false, err
206		}
207		return res, false, nil
208	}
209	
210	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
211	func sameSet(a, b []string) bool {
212		if len(a) != len(b) {
213			return false
214		}
215		x := append([]string(nil), a...)
216		y := append([]string(nil), b...)
217		sort.Strings(x)
218		sort.Strings(y)
219		for i := range x {
220			if x[i] != y[i] {
221				return false
222			}
223		}
224		return true
225	}
226	
227	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
228	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
229	func (s *Store) save() error {
230		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
231			return fmt.Errorf("保存数据文件失败: %w", err)
232		}
233		buf, err := json.MarshalIndent(s.data, "", "  ")
234		if err != nil {
235			return fmt.Errorf("保存数据文件失败: %w", err)
236		}
237		buf = append(buf, '\n')
238	
239		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
240		if err != nil {
241			return fmt.Errorf("保存数据文件失败: %w", err)
242		}
243		tmpName := tmp.Name()
244		cleanup := func() { _ = os.Remove(tmpName) }
245	
246		if _, err := tmp.Write(buf); err != nil {
247			_ = tmp.Close()
248			cleanup()
249			return fmt.Errorf("保存数据文件失败: %w", err)
250		}
251		if err := tmp.Sync(); err != nil {
252			_ = tmp.Close()
253			cleanup()
254			return fmt.Errorf("保存数据文件失败: %w", err)
255		}
256		if err := tmp.Close(); err != nil {
257			cleanup()
258			return fmt.Errorf("保存数据文件失败: %w", err)
259		}
260	
261		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
262		var check ledgerFile
263		if err := json.Unmarshal(buf, &check); err != nil {
264			cleanup()
265			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
266		}
267	
268		if err := os.Rename(tmpName, s.path); err != nil {
269			cleanup()
270			return fmt.Errorf("保存数据文件失败: %w", err)
271		}
272		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
273			_ = dir.Sync()
274			_ = dir.Close()
275		}
276		return nil
277	}
