309			t.Fatal(err)
310		}
311		if err := os.Chmod(ro, 0o555); err != nil {
312			t.Fatal(err)
313		}
314		t.Cleanup(func() { _ = os.Chmod(ro, 0o755) })
315		path := filepath.Join(ro, "ledger.json")
