332	func TestSameSet(t *testing.T) {
333		if !sameSet(nil, nil) {
334			t.Fatal("两个空集合应相同")
335		}
336		if sameSet([]string{"a"}, []string{"a", "b"}) {
337			t.Fatal("长度不同应不同")
338		}
339		if !sameSet([]string{"a", "b"}, []string{"b", "a"}) {
340			t.Fatal("顺序不应影响集合判定")
341		}
342		if sameSet([]string{"a", "b"}, []string{"a", "c"}) {
343			t.Fatal("元素不同应不同")
344		}
345	}
346	
347	func TestWhitespaceIDsAreDataNotAcceptedByCaller(t *testing.T) {
348		// Store 层信任调用方已清洗；空白清洗规则在 CLI 层强制。
349		v, err := cleanID("包裹编号", "  P1  ")
350		if err != nil || v != "P1" {
351			t.Fatalf("cleanID 应去除两端空白: %q %v", v, err)
352		}
353		if _, err := cleanID("包裹编号", "   \t "); err == nil || !strings.Contains(err.Error(), "不可为空") {
354			t.Fatalf("纯空白应报错，得到 %v", err)
355		}
356	}
