	t1 := tClock(2026, 10, 5, 9, 0)
	mustRegister(t, s, "P001", "站点A", t1)
	mustHandoff(t, s, "R1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 10, 0))
	if _, _, err := s.Return("RT1", "R1", "错发", tClock(2026, 10, 5, 11, 0)); err != nil {
