1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// statusInStation 表示包裹当前在某站点（已收件或已完成交接）。
15	const statusInStation = "在站"
16	
17	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
18	type Event struct {
19		Op         string    `json:"op"`                   // 收件 | 交接 | 退回
20		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站）
21		Time       time.Time `json:"time"`                 // 发生时间
22		Request    string    `json:"request,omitempty"`    // 交接/退回请求号（收件记录为空）
23		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
24		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）
25		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）
26	}
27	
28	// Parcel 是一件包裹的台账信息。
29	type Parcel struct {
30		ID         string    `json:"id"`
31		Station    string    `json:"station"`    // 当前归属站点
32		Status     string    `json:"status"`     // 当前状态
33		Registered time.Time `json:"registered"` // 收件时间
34		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
35	}
36	
37	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
38	type HandoffResult struct {
39		Request    string    `json:"request"`
40		From       string    `json:"from"`
41		To         string    `json:"to"`
42		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
43		Time       time.Time `json:"time"`
44		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
45	}
46	
47	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
48	type ReturnResult struct {
49		Request string    `json:"request"` // 退回请求号
50		Handoff string    `json:"handoff"` // 被退回的原交接请求号
51		From    string    `json:"from"`    // 退回源站（原交接目的站）
52		To      string    `json:"to"`      // 退回目的站（原交接源站）
53		Reason  string    `json:"reason"`
54		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
55		Time    time.Time `json:"time"`
56	}
57	
58	// ledgerFile 是本地数据文件的磁盘结构。
59	type ledgerFile struct {
60		Version  int                       `json:"version"`
61		Parcels  map[string]*Parcel        `json:"parcels"`
62		Handoffs map[string]*HandoffResult `json:"handoffs"`
63		Returns  map[string]*ReturnResult  `json:"returns"`
64	}
65	
66	// Store 是一个数据文件对应的包裹站点交接台账。
67	type Store struct {
68		path string
69		data ledgerFile
70	}
71	
72	var (
73		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
74		ErrCorrupt = errors.New("数据文件已损坏")
75		// ErrNotFound 表示包裹编号在台账中不存在。
76		ErrNotFound = errors.New("包裹不存在")
77	)
78	
79	// Open 打开（或在文件不存在时建立）一个本地台账。
80	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
81	func Open(path string) (*Store, error) {
82		s := &Store{path: path}
83		raw, err := os.ReadFile(path)
84		if err != nil {
85			if os.IsNotExist(err) {
86				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{}, Returns: map[string]*ReturnResult{}}
87				return s, nil
88			}
89			return nil, fmt.Errorf("读取数据文件失败: %w", err)
90		}
91		if len(bytes.TrimSpace(raw)) == 0 {
92			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
93		}
94		if err := json.Unmarshal(raw, &s.data); err != nil {
95			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
96		}
97		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
98			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
99		}
100		// 早期版本的数据文件没有 returns 字段：按空退回表处理，无需手工修改。
101		if s.data.Returns == nil {
102			s.data.Returns = map[string]*ReturnResult{}
103		}
104		if err := s.data.validate(); err != nil {
105			return nil, err
106		}
107		return s, nil
108	}
