110	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
111	func (l *ledgerFile) validate() error {
112		for id, p := range l.Parcels {
113			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
114				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
115			}
116			for i, e := range p.Trail {
117				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
118					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
119				}
120				if e.Op == "退回" {
121					if e.Request == "" || e.Reason == "" || e.From == "" {
122						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
123					}
124					if _, ok := l.Handoffs[e.RefRequest]; !ok {
125						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
126					}
127				}
128			}
129		}
130		for req, h := range l.Handoffs {
131			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
132				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
133			}
134			for _, id := range h.Parcels {
135				if _, ok := l.Parcels[id]; !ok {
136					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
137				}
138			}
139			if h.ReturnedBy != "" {
140				r, ok := l.Returns[h.ReturnedBy]
141				if !ok || r.Handoff != req {
142					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
143				}
144			}
145		}
146		for req, r := range l.Returns {
147			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
148				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
149				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
150			}
151			h, ok := l.Handoffs[r.Handoff]
152			if !ok {
153				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
154			}
155			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
156				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
157			}
158			for _, id := range r.Parcels {
159				if _, ok := l.Parcels[id]; !ok {
160					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
161				}
162			}
163		}
164		return nil
165	}
