200	// Handoff 提交一次多件包裹的站点交接。
201	//
202	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
203	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
204	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
205	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
206	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
207		if saved, ok := s.data.Handoffs[request]; ok {
208			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
209				return saved, true, nil
210			}
211			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
212		}
213	
214		// 首次提交：先做全部校验，任何一件不满足都整体失败。
215		for _, id := range parcels {
216			p, ok := s.data.Parcels[id]
217			if !ok {
218				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
219			}
220			if p.Station != from {
221				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
222			}
223		}
224	
225		res := &HandoffResult{
226			Request: request,
227			From:    from,
228			To:      to,
229			Parcels: append([]string(nil), parcels...),
230			Time:    now,
231		}
232		s.data.Handoffs[request] = res
233	
234		// 记录旧值，落盘失败时整体回滚。
235		prev := make(map[string]struct {
236			station string
237			trail   []Event
238		}, len(parcels))
239		for _, id := range parcels {
240			p := s.data.Parcels[id]
241			prev[id] = struct {
242				station string
243				trail   []Event
244			}{p.Station, append([]Event(nil), p.Trail...)}

